import{_ as t,c as a,o as r,am as o}from"./chunks/framework.BeBnCPtr.js";const m=JSON.parse('{"title":"Quickstart","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/quickstart.md","filePath":"introduction/quickstart.md"}'),i={name:"introduction/quickstart.md"};function s(n,e,d,l,h,c){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="quickstart" tabindex="-1">Quickstart <a class="header-anchor" href="#quickstart" aria-label="Permalink to &quot;Quickstart&quot;">​</a></h1><p>It may surprise some that the hypermedia approach described here predates SOAP. I believe the reason hypermedia feels new is approaches like SOAP created a need for tooling which vendors of the day created and sold. There was no money to be made in hypermedia, and related ideas. Without adequate tools, too many developers were never exposed to the idea - and those that were didn&#39;t have an easy way to experiment with it.</p><p>At pointw.com we are contributing to this tool gap.</p><p>To embrace the hypermedia approach, both client and backend have to commit. So we have created two sets of tools:</p><ul><li><a href="https://pointw-dev.github.io/hypermea/" target="_blank" rel="noreferrer">hypermea</a><ul><li>Simple Commands, Serious APIs</li><li>Create production-ready hypermedia APIs <em>fast</em></li></ul></li><li><a href="https://pointw-dev.github.io/halchemy/" target="_blank" rel="noreferrer">halchemy</a><ul><li>HAL for humans</li><li>Create clients for HAL-based APIs with ease and without compromise</li></ul></li></ul>',5)]))}const u=t(i,[["render",s]]);export{m as __pageData,u as default};
